  async initCharts() {
    try {
      if (typeof Chart === "undefined") await AssetLoader.loadScript(CONFIG.CHART_CDN);
    } catch {
      Utils.showToast("تعذر تحميل الرسوم البيانية حالياً", "error");
      return;
    }
    const skills = document.getElementById("chart-skills");
    if (skills && !this.chartSkills) {
      this.chartSkills = new Chart(skills, {
        type: "radar",
        data: {
          labels: ["الفهم القرائي", "حل المسائل", "التفكير النقدي", "الحفظ", "المفاهيم العلمية", "الإبداع"],
          datasets: [{
            label: "المستوى الحالي",
            data: [85, 75, 60, 90, 70, 80],
            fill: true,
            backgroundColor: "rgba(139, 92, 246, 0.2)",
            borderColor: "#8b5cf6",
            pointBackgroundColor: "#fff",
            pointBorderColor: "#fff"
          }]
        },
        options: {
          scales: {
            r: {
              angleLines: { color: "rgba(255, 255, 255, 0.1)" },
              grid: { color: "rgba(255, 255, 255, 0.1)" },
              pointLabels: { color: "#ccc", font: { family: "Tajawal" } },
              ticks: { display: false, backdropColor: "transparent" }
            }
          },
          plugins: { legend: { display: false } }
        }
      });
    }
    const progress = document.getElementById("chart-progress");
    if (progress && !this.chartProgress) {
      this.chartProgress = new Chart(progress, {
        type: "line",
        data: {
          labels: ["أسبوع 1", "أسبوع 2", "أسبوع 3", "أسبوع 4"],
          datasets: [{
            label: "التقدم",
            data: [65, 70, 78, 85],
            borderColor: "#3b82f6",
            backgroundColor: "rgba(59, 130, 246, 0.1)",
            tension: 0.4,
            fill: true
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          scales: {
            y: { grid: { color: "rgba(255,255,255,0.05)" }, ticks: { color: "#aaa" } },
            x: { grid: { display: false }, ticks: { color: "#aaa" } }
          },
          plugins: { legend: { display: false } }
        }
      });
    }
  }

  animateCounter(counter) {
    const target = parseInt(counter.getAttribute("data-target"), 10);
    if (Number.isNaN(target)) return;
    let current = 0;
    const step = Math.ceil(target / (2000 / 16));
    const timer = setInterval(() => {
      current += step;
      if (current >= target) {
        counter.textContent = target.toLocaleString("ar-SA");
        clearInterval(timer);
      } else {
        counter.textContent = current.toLocaleString("ar-SA");
      }
    }, 16);
  }

